use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl SubstitutionPart { # [doc = " Try to turn a replacement into an addition when the span that is being"] # [doc = " overwritten matches either the prefix or suffix of the replacement."] fn trim_trivial_replacements (self , sm : & SourceMap) -> TrimmedSubstitutionPart { let mut trimmed_part = TrimmedSubstitutionPart { original_span : self . span , span : self . span , snippet : self . snippet , } ; if trimmed_part . snippet . is_empty () { return trimmed_part ; } let Ok (snippet) = sm . span_to_snippet (trimmed_part . span) else { return trimmed_part ; } ; if let Some ((prefix , substr , suffix)) = as_substr (& snippet , & trimmed_part . snippet) { trimmed_part . span = Span :: new (trimmed_part . span . lo () + BytePos (prefix as u32) , trimmed_part . span . hi () - BytePos (suffix as u32) , trimmed_part . span . ctxt () , trimmed_part . span . parent () ,) ; trimmed_part . snippet = substr . to_string () ; } trimmed_part } }